   370	  protected _measure_grid(viewport: Size): GridSizeHint {
   371	    const {nrows, ncols, rows, cols, rspacing, cspacing} = this._state
   372	
   373	    const preferred = this._measure_cells((y, x) => {
   374	      const row = rows[y]
   375	      const col = cols[x]
   376	      return {
   377	        width: col.policy == "fixed" ? col.width : Infinity,
   378	        height: row.policy == "fixed" ? row.height : Infinity,
   379	      }
   380	    })
   381	
   382	    let available_height: number
   383	    if (this.sizing.height_policy == "fixed" && this.sizing.height != null) {
   384	      available_height = this.sizing.height
   385	    } else if (viewport.height != Infinity && this.is_height_expanding()) {
   386	      available_height = viewport.height
   387	    } else {
   388	      available_height = preferred.size.height
   389	    }
   390	
   391	    let height_flex = 0
   392	    for (let y = 0; y < nrows; y++) {
   393	      const row = rows[y]
   394	      if (row.policy == "fit" || row.policy == "max") {
   395	        height_flex += row.flex
   396	      } else {
   397	        available_height -= preferred.row_heights[y]
   398	      }
   399	    }
   400	
   401	    available_height -= (nrows - 1)*rspacing
   402	
   403	    if (height_flex != 0 && available_height > 0) {
   404	      for (let y = 0; y < nrows; y++) {
   405	        const row = rows[y]
   406	        if (row.policy == "fit" || row.policy == "max") {
   407	          const height = round(available_height * (row.flex/height_flex))
   408	          available_height -= height
   409	          preferred.row_heights[y] = height
   410	          height_flex -= row.flex
   411	        }
   412	      }
   413	    } else if (available_height < 0) {
   414	      let nadjustable = 0
   415	      for (let y = 0; y < nrows; y++) {
   416	        const row = rows[y]
   417	        if (row.policy != "fixed") {
   418	          nadjustable++
   419	        }
   420	      }
   421	
   422	      let overflow_height = -available_height
   423	      for (let y = 0; y < nrows; y++) {
   424	        const row = rows[y]
   425	        if (row.policy != "fixed") {
   426	          const height = preferred.row_heights[y]
   427	          const cutoff = round(overflow_height/nadjustable)
   428	          preferred.row_heights[y] = max(height - cutoff, 0)
   429	          overflow_height -= cutoff > height ? height : cutoff
   430	          nadjustable--
   431	        }
   432	      }
   433	    }
   434	
   435	    let available_width: number
   436	    if (this.sizing.width_policy == "fixed" && this.sizing.width != null) {
   437	      available_width = this.sizing.width
   438	    } else if (viewport.width != Infinity && this.is_width_expanding()) {
   439	      available_width = viewport.width
   440	    } else {
   441	      available_width = preferred.size.width
   442	    }
   443	
   444	    let width_flex = 0
   445	    for (let x = 0; x < ncols; x++) {
   446	      const col = cols[x]
   447	      if (col.policy == "fit" || col.policy == "max") {
   448	        width_flex += col.flex
   449	      } else {
   450	        available_width -= preferred.col_widths[x]
   451	      }
   452	    }
   453	
   454	    available_width -= (ncols - 1)*cspacing
   455	
   456	    if (width_flex != 0 && available_width > 0) {
   457	      for (let x = 0; x < ncols; x++) {
   458	        const col = cols[x]
   459	        if (col.policy == "fit" || col.policy == "max") {
   460	          const width = round(available_width * (col.flex/width_flex))
   461	          available_width -= width
   462	          preferred.col_widths[x] = width
   463	          width_flex -= col.flex
   464	        }
   465	      }
   466	    } else if (available_width < 0) {
   467	      let nadjustable = 0
   468	      for (let x = 0; x < ncols; x++) {
   469	        const col = cols[x]
   470	        if (col.policy != "fixed") {
   471	          nadjustable++
   472	        }
   473	      }
   474	
   475	      let overflow_width = -available_width
   476	      for (let x = 0; x < ncols; x++) {
   477	        const col = cols[x]
   478	        if (col.policy != "fixed") {
   479	          const width = preferred.col_widths[x]
   480	          const cutoff = round(overflow_width/nadjustable)
   481	          preferred.col_widths[x] = max(width - cutoff, 0)
   482	          overflow_width -= cutoff > width ? width : cutoff
   483	          nadjustable--
   484	        }
   485	      }
   486	    }
   487	
   488	    const {row_heights, col_widths, size_hints} = this._measure_cells((y, x) => {
   489	      return {
   490	        width: preferred.col_widths[x],
   491	        height: preferred.row_heights[y],
   492	      }
   493	    })
   494	
   495	    const size = this._measure_totals(row_heights, col_widths)
   496	    return {size, row_heights, col_widths, size_hints}
   497	  }
   498	
   499	  protected _measure(viewport: Size): SizeHint {
   500	    const {size} = this._measure_grid(viewport)
   501	    return size
   502	  }
