   215	        } else if (isNumber(sizing)) {
   216	          return {policy: "fixed", height: sizing}
   217	        } else if (isString(sizing)) {
   218	          return {policy: sizing} as RowSizing
   219	        } else {
   220	          return sizing
   221	        }
   222	      })()
   223	
   224	      const align = row.align ?? "auto"
   225	
   226	      if (row.policy == "fixed") {
   227	        rows[y] = {policy: "fixed", height: row.height, align}
