 12	export class DefaultMap<K, V> {
 13	  private _map = new Map<K, V>()
 14	
 15	  constructor(readonly def: () => V) {}
 16	
 17	  get(key: K): V {
 18	    let value = this._map.get(key)
 19	    if (value === undefined) {
 20	      value = this.def()
 21	      this._map.set(key, value)
 22	    }
 23	    return value
 24	  }
 25	
 26	  apply(key: K, fn: (val: V) => V): void {
 27	    const value = this.get(key)
 28	    this._map.set(key, fn(value))
 29	  }
 30	}
 31	
 32	export type GridItem<T extends Layoutable> = {
 33	  layout: T
 34	  row: number
 35	  col: number
 36	  row_span?: number
 37	  col_span?: number
 38	}
 39	
 40	export type ItemSizeHint = {
 41	  layout: Layoutable
 42	  size_hint: SizeHint
 43	}
 44	
 45	export type GridSizeHint = {
 46	  size: Size
 47	  size_hints: Container<ItemSizeHint>
 48	  row_heights: number[]
 49	  col_widths: number[]
 50	}
 51	
 52	type TrackAlign = "auto" | Align
 53	
 54	type TrackSpec<T> = (({policy: "fixed"} & T) | {policy: "min"} | {policy: "fit" | "max", flex: number}) & {align: TrackAlign}
 55	
 56	type RowSpec = TrackSpec<{height: number}>
 57	type ColSpec = TrackSpec<{width: number}>
 58	
 59	type GridState = {
 60	  items: Container<Layoutable>
 61	  nrows: number
 62	  ncols: number
 63	  rows: RowSpec[]
 64	  cols: ColSpec[]
 65	  rspacing: number
 66	  cspacing: number
 67	}
 68	
 69	export type QuickTrackSizing = "auto" | "min" | "fit" | "max" | number
 70	
 71	export type RowSizing =
 72	  {policy: "auto" | "min", align?: TrackAlign} |
 73	  {policy: "fit" | "max", flex?: number, align?: TrackAlign} |
 74	  {policy: "fixed", height: number, align?: TrackAlign}
 75	
 76	export type ColSizing =
 77	  {policy: "auto" | "min", align?: TrackAlign} |
 78	  {policy: "fit" | "max", flex?: number, align?: TrackAlign} |
 79	  {policy: "fixed", width: number, align?: TrackAlign}
 80	
 81	export type RowsSizing = QuickTrackSizing | {[key: string]: QuickTrackSizing | RowSizing | undefined}
 82	
 83	export type ColsSizing = QuickTrackSizing | {[key: string]: QuickTrackSizing | ColSizing | undefined}
 84	
 85	type Span = {r0: number, c0: number, r1: number, c1: number}
 86	
 87	export class Container<T> {
 88	  private readonly _items: {span: Span, data: T}[] = []
 89	
 90	  get size(): number {
 91	    return this._items.length
 92	  }
 93	
 94	  private _nrows: number = 0
 95	  private _ncols: number = 0
 96	
 97	  get nrows(): number {
 98	    return this._nrows
 99	  }
100	  get ncols(): number {
101	    return this._ncols
102	  }
103	
104	  add(span: Span, data: T): void {
105	    const {r1, c1} = span
106	    this._nrows = max(this._nrows, r1 + 1)
107	    this._ncols = max(this._ncols, c1 + 1)
108	    this._items.push({span, data})
109	  }
110	
111	  at(r: number, c: number): T[] {
112	    const selected = this._items.filter(({span}) => {
113	      return span.r0 <= r && r <= span.r1 &&
114	             span.c0 <= c && c <= span.c1
115	    })
116	    return selected.map(({data}) => data)
117	  }
118	
119	  row(r: number): T[] {
120	    const selected = this._items.filter(({span}) => span.r0 <= r && r <= span.r1)
121	    return selected.map(({data}) => data)
122	  }
123	
124	  col(c: number): T[] {
125	    const selected = this._items.filter(({span}) => span.c0 <= c && c <= span.c1)
126	    return selected.map(({data}) => data)
127	  }
128	
129	  *[Symbol.iterator](): Generator<{span: Span, data: T}, void, undefined> {
130	    yield* this._items
131	  }
132	
133	  foreach(fn: (span: Span, data: T) => void): void {
134	    for (const {span, data} of this._items) {
135	      fn(span, data)
136	    }
137	  }
138	
139	  map<U>(fn: (span: Span, data: T) => U): Container<U> {
140	    const result = new Container<U>()
141	    for (const {span, data} of this._items) {
142	      result.add(span, fn(span, data))
143	    }
144	    return result
145	  }
146	}
147	
148	export class Grid<T extends Layoutable = Layoutable> extends Layoutable {
149	  override *[Symbol.iterator]() {
150	    for (const {layout} of this.items) {
151	      yield layout
152	    }
153	  }
154	
155	  rows: RowsSizing = "auto"
156	  cols: ColsSizing = "auto"
157	
158	  spacing: number | [number, number] = 0
159	
160	  private _state: GridState
161	
162	  constructor(public items: GridItem<T>[] = []) {
163	    super()
164	  }
165	
166	  override is_width_expanding(): boolean {
167	    if (super.is_width_expanding()) {
168	      return true
169	    }
170	
171	    if (this.sizing.width_policy == "fixed") {
172	      return false
173	    }
174	
175	    const {cols} = this._state
176	    return some(cols, (col) => col.policy == "max")
177	  }
178	
179	  override is_height_expanding(): boolean {
180	    if (super.is_height_expanding()) {
181	      return true
182	    }
183	
184	    if (this.sizing.height_policy == "fixed") {
185	      return false
186	    }
187	
188	    const {rows} = this._state
189	    return some(rows, (row) => row.policy == "max")
190	  }
191	
192	  protected override _init(): void {
193	    super._init()
194	
195	    const items = new Container<Layoutable>()
196	    for (const {layout, row, col, row_span=1, col_span=1} of this.items) {
197	      if (layout.sizing.visible) {
198	        const r0 = row
199	        const c0 = col
200	        const r1 = row + row_span - 1
201	        const c1 = col + col_span - 1
202	        items.add({r0, c0, r1, c1}, layout)
203	      }
204	    }
205	
206	    const {nrows, ncols} = items
207	
208	    const rows: RowSpec[] = new Array(nrows)
209	    for (let y = 0; y < nrows; y++) {
210	      const row = ((): RowSizing => {
211	        const sizing = isPlainObject(this.rows) ? this.rows[y] ?? this.rows["*"] : this.rows
212	
213	        if (sizing == null) {
214	          return {policy: "auto"}
215	        } else if (isNumber(sizing)) {
216	          return {policy: "fixed", height: sizing}
217	        } else if (isString(sizing)) {
218	          return {policy: sizing} as RowSizing
219	        } else {
220	          return sizing
221	        }
222	      })()
223	
224	      const align = row.align ?? "auto"
225	
226	      if (row.policy == "fixed") {
227	        rows[y] = {policy: "fixed", height: row.height, align}
228	      } else if (row.policy == "min") {
229	        rows[y] = {policy: "min", align}
230	      } else if (row.policy == "fit" || row.policy == "max") {
231	        rows[y] = {policy: row.policy, flex: row.flex ?? 1, align}
232	      } else {
233	        if (some(items.row(y), (layout) => layout.is_height_expanding())) {
234	          rows[y] = {policy: "max", flex: 1, align}
235	        } else {
236	          rows[y] = {policy: "min", align}
237	        }
238	      }
239	    }
240	
241	    const cols: ColSpec[] = new Array(ncols)
242	    for (let x = 0; x < ncols; x++) {
243	      const col = ((): ColSizing => {
244	        const sizing = isPlainObject(this.cols) ? this.cols[x] ?? this.cols["*"] : this.cols
245	
246	        if (sizing == null) {
247	          return {policy: "auto"}
248	        } else if (isNumber(sizing)) {
249	          return {policy: "fixed", width: sizing}
250	        } else if (isString(sizing)) {
251	          return {policy: sizing} as ColSizing
252	        } else {
253	          return sizing
254	        }
255	      })()
256	
257	      const align = col.align ?? "auto"
258	
259	      if (col.policy == "fixed") {
260	        cols[x] = {policy: "fixed", width: col.width, align}
261	      } else if (col.policy == "min") {
262	        cols[x] = {policy: "min", align}
263	      } else if (col.policy == "fit" || col.policy == "max") {
264	        cols[x] = {policy: col.policy, flex: col.flex ?? 1, align}
265	      } else {
266	        if (some(items.col(x), (layout) => layout.is_width_expanding())) {
267	          cols[x] = {policy: "max", flex: 1, align}
268	        } else {
269	          cols[x] = {policy: "min", align}
270	        }
271	      }
272	    }
273	
274	    const [rspacing, cspacing] =
275	      isNumber(this.spacing) ? [this.spacing, this.spacing] : this.spacing
276	
277	    this._state = {items, nrows, ncols, rows, cols, rspacing, cspacing}
278	  }
279	
280	  protected _measure_totals(row_heights: number[], col_widths: number[]): Size {
281	    const {nrows, ncols, rspacing, cspacing} = this._state
282	    return {
283	      height: sum(row_heights) + (nrows - 1)*rspacing,
284	      width: sum(col_widths) + (ncols - 1)*cspacing,
285	    }
286	  }
287	
288	  protected _measure_cells(cell_viewport: (r: number, c: number) => Size): GridSizeHint {
289	    const {items, nrows, ncols, rows, cols, rspacing, cspacing} = this._state
290	
291	    const row_heights: number[] = new Array(nrows)
292	    for (let r = 0; r < nrows; r++) {
293	      const row = rows[r]
294	      row_heights[r] = row.policy == "fixed" ? row.height : 0
295	    }
296	
297	    const col_widths: number[] = new Array(ncols)
298	    for (let c = 0; c < ncols; c++) {
299	      const col = cols[c]
300	      col_widths[c] = col.policy == "fixed" ? col.width : 0
301	    }
302	
303	    const size_hints = new Container<ItemSizeHint>()
304	
305	    items.foreach((span, layout) => {
306	      const {r0, c0, r1, c1} = span
307	
308	      const rspace = (r1 - r0)*rspacing
309	      const cspace = (c1 - c0)*cspacing
310	
311	      let height = 0
312	      for (let r = r0; r <= r1; r++) {
313	        height += cell_viewport(r, c0).height
314	      }
315	      height += rspace
316	
317	      let width = 0
318	      for (let c = c0; c <= c1; c++) {
319	        width += cell_viewport(r0, c).width
320	      }
321	      width += cspace
322	
323	      const size_hint = layout.measure({width, height})
324	      size_hints.add(span, {layout, size_hint})
325	
326	      const size = new Sizeable(size_hint).grow_by(layout.sizing.margin)
327	
328	      size.height -= rspace
329	      size.width -= cspace
330	
331	      const radjustable = []
332	      for (let r = r0; r <= r1; r++) {
333	        const row = rows[r]
334	        if (row.policy == "fixed") {
335	          size.height -= row.height
336	        } else {
337	          radjustable.push(r)
338	        }
339	      }
340	
341	      if (size.height > 0) {
342	        const rheight = round(size.height/radjustable.length)
343	        for (const r of radjustable) {
344	          row_heights[r] = max(row_heights[r], rheight)
345	        }
346	      }
347	
348	      const cadjustable = []
349	      for (let c = c0; c <= c1; c++) {
350	        const col = cols[c]
351	        if (col.policy == "fixed") {
352	          size.width -= col.width
353	        } else {
354	          cadjustable.push(c)
355	        }
356	      }
357	
358	      if (size.width > 0) {
359	        const cwidth = round(size.width/cadjustable.length)
360	        for (const c of cadjustable) {
361	          col_widths[c] = max(col_widths[c], cwidth)
362	        }
363	      }
364	    })
365	
366	    const size = this._measure_totals(row_heights, col_widths)
367	    return {size, row_heights, col_widths, size_hints}
368	  }
369	
370	  protected _measure_grid(viewport: Size): GridSizeHint {
371	    const {nrows, ncols, rows, cols, rspacing, cspacing} = this._state
372	
373	    const preferred = this._measure_cells((y, x) => {
374	      const row = rows[y]
375	      const col = cols[x]
376	      return {
377	        width: col.policy == "fixed" ? col.width : Infinity,
378	        height: row.policy == "fixed" ? row.height : Infinity,
379	      }
380	    })
381	
382	    let available_height: number
383	    if (this.sizing.height_policy == "fixed" && this.sizing.height != null) {
384	      available_height = this.sizing.height
385	    } else if (viewport.height != Infinity && this.is_height_expanding()) {
386	      available_height = viewport.height
387	    } else {
388	      available_height = preferred.size.height
389	    }
390	
391	    let height_flex = 0
392	    for (let y = 0; y < nrows; y++) {
393	      const row = rows[y]
394	      if (row.policy == "fit" || row.policy == "max") {
395	        height_flex += row.flex
396	      } else {
397	        available_height -= preferred.row_heights[y]
398	      }
399	    }
400	
401	    available_height -= (nrows - 1)*rspacing
402	
403	    if (height_flex != 0 && available_height > 0) {
404	      for (let y = 0; y < nrows; y++) {
405	        const row = rows[y]
406	        if (row.policy == "fit" || row.policy == "max") {
407	          const height = round(available_height * (row.flex/height_flex))
408	          available_height -= height
409	          preferred.row_heights[y] = height
410	          height_flex -= row.flex
411	        }
412	      }
413	    } else if (available_height < 0) {
414	      let nadjustable = 0
415	      for (let y = 0; y < nrows; y++) {
416	        const row = rows[y]
417	        if (row.policy != "fixed") {
418	          nadjustable++
419	        }
420	      }
421	
422	      let overflow_height = -available_height
423	      for (let y = 0; y < nrows; y++) {
424	        const row = rows[y]
425	        if (row.policy != "fixed") {
426	          const height = preferred.row_heights[y]
427	          const cutoff = round(overflow_height/nadjustable)
428	          preferred.row_heights[y] = max(height - cutoff, 0)
429	          overflow_height -= cutoff > height ? height : cutoff
430	          nadjustable--
431	        }
432	      }
433	    }
434	
435	    let available_width: number
436	    if (this.sizing.width_policy == "fixed" && this.sizing.width != null) {
437	      available_width = this.sizing.width
438	    } else if (viewport.width != Infinity && this.is_width_expanding()) {
439	      available_width = viewport.width
440	    } else {
441	      available_width = preferred.size.width
442	    }
443	
444	    let width_flex = 0
445	    for (let x = 0; x < ncols; x++) {
446	      const col = cols[x]
447	      if (col.policy == "fit" || col.policy == "max") {
448	        width_flex += col.flex
449	      } else {
450	        available_width -= preferred.col_widths[x]
451	      }
452	    }
453	
454	    available_width -= (ncols - 1)*cspacing
455	
456	    if (width_flex != 0 && available_width > 0) {
457	      for (let x = 0; x < ncols; x++) {
458	        const col = cols[x]
459	        if (col.policy == "fit" || col.policy == "max") {
460	          const width = round(available_width * (col.flex/width_flex))
461	          available_width -= width
462	          preferred.col_widths[x] = width
463	          width_flex -= col.flex
464	        }
465	      }
466	    } else if (available_width < 0) {
467	      let nadjustable = 0
468	      for (let x = 0; x < ncols; x++) {
469	        const col = cols[x]
470	        if (col.policy != "fixed") {
471	          nadjustable++
472	        }
473	      }
474	
475	      let overflow_width = -available_width
476	      for (let x = 0; x < ncols; x++) {
477	        const col = cols[x]
478	        if (col.policy != "fixed") {
479	          const width = preferred.col_widths[x]
480	          const cutoff = round(overflow_width/nadjustable)
481	          preferred.col_widths[x] = max(width - cutoff, 0)
482	          overflow_width -= cutoff > width ? width : cutoff
483	          nadjustable--
484	        }
485	      }
486	    }
487	
488	    const {row_heights, col_widths, size_hints} = this._measure_cells((y, x) => {
489	      return {
490	        width: preferred.col_widths[x],
491	        height: preferred.row_heights[y],
492	      }
493	    })
494	
495	    const size = this._measure_totals(row_heights, col_widths)
496	    return {size, row_heights, col_widths, size_hints}
497	  }
498	
499	  protected _measure(viewport: Size): SizeHint {
500	    const {size} = this._measure_grid(viewport)
501	    return size
502	  }
503	
504	  protected override _set_geometry(outer: BBox, inner: BBox): void {
505	    super._set_geometry(outer, inner)
506	
507	    const {nrows, ncols, rspacing, cspacing} = this._state
508	
509	    const {row_heights, col_widths, size_hints} = this._measure_grid(outer)
510	
511	    const rows = this._state.rows.map((row, r): RowSpec & {top: number, height: number, bottom: number} => {
512	      return {...row, top: 0, height: row_heights[r], get bottom() {
513	        return this.top + this.height
514	      }}
515	    })
516	
517	    const cols = this._state.cols.map((col, c): ColSpec & {left: number, width: number, right: number} => {
518	      return {...col, left: 0, width: col_widths[c], get right() {
519	        return this.left + this.width
520	      }}
521	    })
522	
523	    const items = size_hints.map((_, item) => {
524	      return {...item, outer: new BBox(), inner: new BBox()}
525	    })
526	
527	    for (let r = 0, top = !this.absolute ? this.position.top : outer.top; r < nrows; r++) {
528	      const row = rows[r]
529	      row.top = top
530	      top += row.height + rspacing
531	    }
532	
533	    for (let c = 0, left = !this.absolute ? this.position.left : outer.left; c < ncols; c++) {
534	      const col = cols[c]
535	      col.left = left
536	      left += col.width + cspacing
537	    }
538	
539	    function span_width(c0: number, c1: number) {
540	      let width = (c1 - c0)*cspacing
541	      for (let c = c0; c <= c1; c++) {
542	        width += cols[c].width
543	      }
544	      return width
545	    }
546	
547	    function span_height(r0: number, r1: number) {
548	      let height = (r1 - r0)*rspacing
549	      for (let r = r0; r <= r1; r++) {
550	        height += rows[r].height
551	      }
552	      return height
553	    }
554	
555	    items.foreach(({r0, c0, r1, c1}, item) => {
556	      const {layout, size_hint} = item
557	
558	      const {sizing} = layout
559	      const {width, height} = size_hint
560	
561	      const span = {
562	        width: span_width(c0, c1),
563	        height: span_height(r0, r1),
564	      }
565	
566	      const halign = c0 == c1 && cols[c0].align != "auto" ? cols[c0].align : sizing.halign
567	      const valign = r0 == r1 && rows[r0].align != "auto" ? rows[r0].align : sizing.valign
568	
569	      let left = cols[c0].left
570	      if (halign == "start") {
571	        left += sizing.margin.left
572	      } else if (halign == "center") {
573	        left += round((span.width - width)/2)
574	      } else if (halign == "end") {
575	        left += span.width - sizing.margin.right - width
576	      }
577	
578	      let top = rows[r0].top
579	      if (valign == "start") {
580	        top += sizing.margin.top
581	      } else if (valign == "center") {
582	        top += round((span.height - height)/2)
583	      } else if (valign == "end") {
584	        top += span.height - sizing.margin.bottom - height
585	      }
586	
587	      item.outer = new BBox({left, top, width, height})
588	    })
589	
590	    type Aligns = {
591	      start: DefaultMap<number, number>
592	      end: DefaultMap<number, number>
593	    }
594	
595	    const row_aligns = rows.map((): Aligns => {
596	      return {
597	        start: new DefaultMap(() => 0),
598	        end: new DefaultMap(() => 0),
599	      }
600	    })
601	    const col_aligns = cols.map((): Aligns => {
602	      return {
603	        start: new DefaultMap(() => 0),
604	        end: new DefaultMap(() => 0),
605	      }
606	    })
607	
608	    items.foreach(({r0, c0, r1, c1}, {size_hint, outer}) => {
609	      const {inner} = size_hint
610	
611	      if (inner != null) {
612	        row_aligns[r0].start.apply(outer.top, (v) => max(v, inner.top))
613	        row_aligns[r1].end.apply(rows[r1].bottom - outer.bottom, (v) => max(v, inner.bottom))
614	
615	        col_aligns[c0].start.apply(outer.left, (v) => max(v, inner.left))
616	        col_aligns[c1].end.apply(cols[c1].right - outer.right, (v) => max(v, inner.right))
617	      }
618	    })
619	
620	    items.foreach(({r0, c0, r1, c1}, item) => {
621	      const {size_hint, outer} = item
622	
623	      const inner_bbox = (extents: Extents) => {
624	        const outer_bbox = this.absolute ? outer : outer.relative()
625	
626	        const left = outer_bbox.left + extents.left
627	        const top = outer_bbox.top + extents.top
628	        const right = outer_bbox.right - extents.right
629	        const bottom = outer_bbox.bottom - extents.bottom
630	
631	        return new BBox({left, top, right, bottom})
632	      }
633	
634	      if (size_hint.inner != null) {
635	        let inner = inner_bbox(size_hint.inner)
636	
637	        //if (size_hint.align !== false) {
638	        const top = row_aligns[r0].start.get(outer.top)
639	        const bottom = row_aligns[r1].end.get(rows[r1].bottom - outer.bottom)
640	
641	        const left = col_aligns[c0].start.get(outer.left)
642	        const right = col_aligns[c1].end.get(cols[c1].right - outer.right)
643	
644	        try {
645	          inner = inner_bbox({top, bottom, left, right})
646	        } catch {}
647	        //}
648	
649	        item.inner = inner
650	      } else {
651	        item.inner = outer
652	      }
653	    })
654	
655	    items.foreach((_, {layout, outer, inner}) => {
656	      layout.set_geometry(outer, inner)
657	    })
658	  }
659	}
660	
661	export class Row extends Grid {
662	  constructor(items: Layoutable[]) {
663	    super()
664	    this.items = items.map((item, i) => ({layout: item, row: 0, col: i}))
665	    this.rows = "fit"
666	  }
667	}
668	
669	export class Column extends Grid {
670	  constructor(items: Layoutable[]) {
671	    super()
672	    this.items = items.map((item, i) => ({layout: item, row: i, col: 0}))
673	    this.cols = "fit"
674	  }
675	}

