1	import type {SizeHint, Size} from "./types"
     2	import {Layoutable} from "./layoutable"
     3	import {BBox} from "../util/bbox"
     4	
     5	const {max, round} = Math
     6	
     7	export abstract class Stack extends Layoutable {
     8	  override *[Symbol.iterator]() {
     9	    yield* this.children
    10	  }
    11	
    12	  children: Layoutable[] = []
    13	}
    14	
    15	export class HStack extends Stack {
    16	  protected _measure(_viewport: Size): SizeHint {
    17	    let width = 0
    18	    let height = 0
    19	
