    25	    children.foreach(({r0, c0, r1, c1}, {layout, model}) => {
    26	      // `layout.visible` is only updated after measuring, so it can be stale here.
    27	      if (!(layout instanceof BorderLayout) || !model.visible) {
    28	        return
    29	      }
