    31	      // they could never shrink again.
    32	      layout.align_border = {left: 0, top: 0, right: 0, bottom: 0}
    33	      const {inner} = layout.measure({width: Infinity, height: Infinity})
    34	      if (inner != null) {
    35	        rows[r0].top = max(rows[r0].top, inner.top)
    36	        rows[r1].bottom = max(rows[r1].bottom, inner.bottom)
