    47	      // itself, matching which sides `_set_geometry` goes on to align.
    48	      const {aligns} = layout
    49	      layout.align_border = {
    50	        left: aligns.left ? cols[c1].left : 0,
    51	        right: aligns.right ? cols[c0].right : 0,
    52	        top: aligns.top ? rows[r0].top : 0,
