 18	   * aligning the frames cannot take space a child needs for its own borders.
 19	   */
 20	  align_borders(): void {
 21	    const {children} = this
 22	    const rows = Array.from({length: children.nrows}, () => ({top: 0, bottom: 0}))
 23	    const cols = Array.from({length: children.ncols}, () => ({left: 0, right: 0}))
 24	
 25	    children.foreach(({r0, c0, r1, c1}, {layout, model}) => {
 26	      // `layout.visible` is only updated after measuring, so it can be stale here.
 27	      if (!(layout instanceof BorderLayout) || !model.visible) {
 28	        return
 29	      }
 30	      // A child's measurement must not carry the previous pass's borders, or
 31	      // they could never shrink again.
 32	      layout.align_border = {left: 0, top: 0, right: 0, bottom: 0}
 33	      const {inner} = layout.measure({width: Infinity, height: Infinity})
 34	      if (inner != null) {
 35	        rows[r0].top = max(rows[r0].top, inner.top)
 36	        rows[r1].bottom = max(rows[r1].bottom, inner.bottom)
 37	        cols[c0].left = max(cols[c0].left, inner.left)
 38	        cols[c1].right = max(cols[c1].right, inner.right)
 39	      }
 40	    })
 41	
 42	    children.foreach(({r0, c0, r1, c1}, {layout}) => {
 43	      if (!(layout instanceof BorderLayout)) {
 44	        return
 45	      }
 46	      // A side opted out of alignment keeps the border it measured for
 47	      // itself, matching which sides `_set_geometry` goes on to align.
 48	      const {aligns} = layout
 49	      layout.align_border = {
 50	        left: aligns.left ? cols[c1].left : 0,
 51	        right: aligns.right ? cols[c0].right : 0,
 52	        top: aligns.top ? rows[r0].top : 0,
 53	        bottom: aligns.bottom ? rows[r1].bottom : 0,
