mkdir -p /tmp/t && cd /tmp/t && cat > page.html <<'E'
<html><head><script src="/app/bokehjs/build/js/bokeh.js"></script><script src="/app/bokehjs/build/js/bokeh-api.js"></script></head>
<body><div id="r"></div><script>
const {figure, column, row} = Bokeh.Plotting
function mk(opts, ylab, big) {
  const p = figure({frame_width: 200, frame_height: 150, title: opts.title, toolbar_location: opts.tl ?? "right", y_axis_label: ylab})
  p.scatter([1,2,3], big ? [1e6, 2e7, 3e8] : [1,2,3])
  return p
}
window.go = async (kind) => {
  const a = mk({title: "A"}, "short")
  const b = mk({title: null, tl: "above"}, "a much longer label\nline two", true)
  const c = mk({title: "C"}, "y", false)
